/// Recursively overwrite field defaults in `schema` with the values from the
/// serialized default state. This ensures the schema's defaults reflect the
/// typed state's custom `Default` impl, which schemars' derive macro cannot
/// always see for nested structs.
fn apply_state_defaults(schema: &mut PluginSchema, state: &Value) {
    fn set_field_defaults(field: &mut op_state_store::FieldSchema, value: &Value) {
        field.default = Some(value.clone());
        if let op_state_store::FieldType::Object(ref mut inner) = field.field_type {
            if let Some(obj) = value.as_object() {
                for (k, v) in obj.iter() {
                    if let Some(f) = inner.get_mut(k.as_str()) {
                        set_field_defaults(f, v);
                    }
                }
            }
        }
    }

    if let Some(obj) = state.as_object() {
        for (k, v) in obj.iter() {
            if let Some(f) = schema.fields.get_mut(k.as_str()) {
                set_field_defaults(f, v);
            }
        }
    }
}

/// Derived `web_ui` schema from the typed [`WebUiState`] struct via schemars.
pub(crate) fn web_ui_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(WebUiState))
        .expect("schemars schema serializes to JSON");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        "web_ui",
        "1.0.0",
        "Web UI state — identity, tunables, and capabilities",
        &root,
    );
    let state = simd_json::serde::to_owned_value(&WebUiState::default())
        .expect("WebUiState default serializes");
    apply_state_defaults(&mut schema, &state);
    schema
}

