    async fn test_plugin_state() {
        let plugin = WebUiPlugin::new();
        assert_eq!(plugin.name(), "web_ui");
        assert!(plugin.is_available());

        let state = plugin.query_current_state().await.unwrap();
        assert!(state.is_object());
    }

